/* ===================== BÀI 46 · Monitor bare-metal ===================== */
/* Bài 46 · Monitor bare-metal (AMTS-EMB-002-M12-L02, X86-046) — sinh bởi tools/author/mpu8086/l46.py, không sửa tay.
   Ví dụ cho trainer 8086 ảo (makeX86Trainer) và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P46=[{"label": "Ví dụ: khởi tạo 8251A, in lời chào", "code": "; Ví dụ 1: khởi tạo 8251A rồi in lời chào ra terminal\nDATA51  EQU     98H                     ; 8251A dữ liệu\nCTRL51  EQU     9AH                     ; 8251A điều khiển / trạng thái\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H               ; ngăn xếp ở đỉnh RAM\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8 bit, không P, 1 stop\n        OUT     CTRL51, AL\n        MOV     AL, 37H                 ; từ lệnh: TxEN, DTR, RxE, ER, RTS\n        OUT     CTRL51, AL\n        MOV     SI, OFFSET chao\n        CALL    inChuoi\n        HLT\ninChuoi PROC    NEAR                    ; in chuỗi CS:SI, kết thúc bằng 0\n        MOV     AL, CS:[SI]             ; chuỗi nằm trong EPROM\n        CMP     AL, 0\n        JE      ic9\n        CALL    gui\n        INC     SI\n        JMP     inChuoi\nic9:\n        RET\ninChuoi ENDP\ngui     PROC    NEAR                    ; gửi AL khi TxRDY = 1\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H                 ; bit 0 = TxRDY\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\nchao    DB      'AMTS-86', 13, 10, 0\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Khởi động tối thiểu cho terminal: ngăn xếp, từ chế độ 4Eh rồi từ lệnh 37h, sau đó in chuỗi đặt trong EPROM bằng MOV AL, CS:[SI] (15 chu kỳ, có tiền tố CS). Mỗi ký tự: 114 chu kỳ CPU. Terminal hiện AMTS-86 rồi xuống dòng. Đoán trước: TxRDY nằm ở bit nào của cổng 9Ah? Đáp án bit 0."}, {"label": "Ví dụ: chép giá trị đầu từ ROM sang RAM", "code": "; Ví dụ 2: chép giá trị đầu của biến từ EPROM sang RAM\nRAM     SEGMENT\ndem     DB      ?                       ; giá trị đầu 0\nbuoc    DB      ?                       ; giá trị đầu 1\nten     DB      8 DUP(?)                ; giá trị đầu 'AMTS-86', 0\nRAM     ENDS\nROM     SEGMENT\n        ASSUME  CS:ROM, DS:RAM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     AX, CS                  ; DS:SI = bảng giá trị đầu trong ROM\n        MOV     DS, AX\n        MOV     SI, OFFSET giaTri\n        MOV     AX, RAM                 ; ES:DI = đầu đoạn RAM (00400h)\n        MOV     ES, AX\n        XOR     DI, DI\n        MOV     CX, 10                  ; 1 + 1 + 8 byte\n        CLD\n        REP     MOVSB                   ; 9 + 17 x 10 = 179 chu kỳ\n        MOV     DS, AX                  ; từ đây DS = RAM\n        MOV     AL, 82H\n        OUT     86H, AL\n        MOV     AL, buoc\n        ADD     AL, dem\n        OUT     80H, AL                 ; LED = buoc + dem = 01h\n        HLT\ngiaTri  DB      0, 1, 'AMTS-86', 0\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Ba biến trong RAM chưa có giá trị khi bật nguồn. Bảng giaTri trong ROM chứa giá trị đầu; REP MOVSB chép 10 byte DS:SI (ROM) → ES:DI (RAM 00400h) trong 9 + 17 × 10 = 179 chu kỳ. Sau đó DS = RAM. Xem phần Bộ nhớ ở 00400h: 00 01 'AMTS-86' 00. LED = buoc + dem = 01h. Đoán trước: trước REP MOVSB, ô 00400h có bằng 0 không? Đáp án không (rác lúc bật nguồn)."}, {"label": "Ví dụ: in công tắc dạng hệ 16", "code": "; Ví dụ 3: in giá trị công tắc dạng hai chữ số hệ 16\nDATA51  EQU     98H\nCTRL51  EQU     9AH\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     AL, 4EH\n        OUT     CTRL51, AL\n        MOV     AL, 37H\n        OUT     CTRL51, AL\n        MOV     AL, 82H                 ; 8255A: PA ra, PB vào\n        OUT     86H, AL\n        IN      AL, 82H                 ; AL = công tắc\n        CALL    inHex\n        HLT\ninHex   PROC    NEAR                    ; in AL dạng 2 chữ số hệ 16\n        PUSH    AX\n        MOV     CL, 4\n        SHR     AL, CL                  ; 4 bit cao xuống thấp\n        CALL    inNib\n        POP     AX\n        AND     AL, 0FH                 ; 4 bit thấp\n        CALL    inNib\n        RET\ninHex   ENDP\ninNib   PROC    NEAR                    ; AL = 0-15 -> '0'-'9', 'A'-'F'\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     n1\n        ADD     AL, 7                   ; '9' + 1 + 7 = 'A'\nn1:\n        CALL    gui\n        RET\ninNib   ENDP\ngui     PROC    NEAR\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "inHex in byte bằng hai chữ số: SHR AL, CL (CL = 4) lấy nửa cao Bh → 'B' (cộng '0' rồi cộng 7), AND 0Fh lấy nửa thấp 5 → '5'. Công tắc đặt sẵn B5h; bấm đổi công tắc rồi chạy lại để thử. Đoán trước: SHR AL, CL với CL = 4 tốn bao nhiêu chu kỳ? Đáp án 8 + 4 × 4 = 24.", "sw": 181}, {"label": "Ví dụ: vòng lệnh L, S, Q của monitor", "code": "; Ví dụ 4: vòng lệnh của monitor: Lxx (LED), S (công tắc), Q\nDATA51  EQU     98H\nCTRL51  EQU     9AH\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     AL, 4EH\n        OUT     CTRL51, AL\n        MOV     AL, 37H\n        OUT     CTRL51, AL\n        MOV     AL, 82H                 ; PA ra (LED), PB vào (công tắc)\n        OUT     86H, AL\nlap:\n        MOV     AL, '>'                 ; dấu nhắc\n        CALL    gui\n        CALL    nhan\n        CALL    gui                     ; hiện lại phím vừa nhận\n        CMP     AL, 'L'\n        JE      lenhL\n        CMP     AL, 'S'\n        JE      lenhS\n        CMP     AL, 'Q'\n        JE      thoat\n        MOV     AL, '?'                 ; lệnh lạ\n        CALL    gui\n        JMP     xuong\nlenhL:\n        CALL    nhanHex                 ; AL = byte từ 2 chữ số hệ 16\n        OUT     80H, AL\n        JMP     xuong\nlenhS:\n        MOV     AL, '='\n        CALL    gui\n        IN      AL, 82H\n        CALL    inHex\nxuong:\n        MOV     AL, 13                  ; về đầu dòng, xuống dòng\n        CALL    gui\n        MOV     AL, 10\n        CALL    gui\n        JMP     lap\nthoat:\n        HLT\nnhanHex PROC    NEAR                    ; nhận 2 chữ số hệ 16 -> AL\n        CALL    nhan\n        CALL    gui\n        CALL    hexVal\n        MOV     CL, 4\n        SHL     AL, CL\n        MOV     BL, AL                  ; 4 bit cao\n        CALL    nhan\n        CALL    gui\n        CALL    hexVal\n        OR      AL, BL\n        RET\nnhanHex ENDP\nhexVal  PROC    NEAR                    ; '0'-'9', 'A'-'F' -> 0-15\n        SUB     AL, '0'\n        CMP     AL, 9\n        JBE     h1\n        SUB     AL, 7\nh1:\n        RET\nhexVal  ENDP\ninHex   PROC    NEAR\n        PUSH    AX\n        MOV     CL, 4\n        SHR     AL, CL\n        CALL    inNib\n        POP     AX\n        AND     AL, 0FH\n        CALL    inNib\n        RET\ninHex   ENDP\ninNib   PROC    NEAR\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     n1\n        ADD     AL, 7\nn1:\n        CALL    gui\n        RET\ninNib   ENDP\ngui     PROC    NEAR\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\nnhan    PROC    NEAR                    ; chờ RxRDY rồi đọc ký tự\n        IN      AL, CTRL51\n        TEST    AL, 02H                 ; bit 1 = RxRDY\n        JZ      nhan\n        IN      AL, DATA51\n        RET\nnhan    ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "L3CSXQ", "note": "Vòng lệnh: ô Ký tự terminal gửi tới có sẵn L3CSXQ. L3C ghi 3Ch ra LED, S in =B5, X là lệnh lạ nên in ?, Q dừng. Mỗi lệnh in lại ký tự đã gõ và xuống dòng. Thử gõ chuỗi lệnh khác (chữ hoa). Đoán trước: sau L3C, LED nào sáng? Đáp án 3Ch = 0011 1100b: LED 5, 4, 3, 2.", "sw": 181}, {"label": "Lỗi: từ lệnh ghi trước từ chế độ", "code": "; Ví dụ 5 (LỖI): ghi từ lệnh trước từ chế độ cho 8251A\nDATA51  EQU     98H\nCTRL51  EQU     9AH\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     AL, 37H                 ; SAI: 8251A hiểu byte đầu là từ chế độ\n        OUT     CTRL51, AL\n        MOV     AL, 4EH                 ; ... và byte này là từ lệnh (IR = 1)\n        OUT     CTRL51, AL\n        MOV     AL, 'K'\n        CALL    gui\n        HLT\ngui     PROC    NEAR\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Lỗi cố ý: ghi 37h trước. 8251A nhận 37h là từ chế độ (khác 4Eh nên trainer ghi chẩn đoán) và 4Eh là từ lệnh có bit IR = 1: reset trong, chip lại chờ từ chế độ. Chữ K không được gửi; terminal trống. Sửa: luôn ghi từ chế độ trước, từ lệnh sau (Ví dụ 1). Đoán trước: terminal có chữ K không? Đáp án không."}, {"label": "Bẫy: lệnh ghi không kiểm địa chỉ", "code": "; Ví dụ 6 (BẪY): lệnh ghi Waaaavv không kiểm giới hạn địa chỉ\nDATA51  EQU     98H\nCTRL51  EQU     9AH\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     ES, AX                  ; ES = 0: địa chỉ aaaa = 0000:aaaa\n        MOV     AL, 4EH\n        OUT     CTRL51, AL\n        MOV     AL, 37H\n        OUT     CTRL51, AL\nlap:\n        CALL    nhan\n        CMP     AL, 'W'\n        JNE     thoat\n        CALL    lenhW\n        JMP     lap\nthoat:\n        HLT\nlenhW   PROC    NEAR                    ; Waaaavv: ghi vv vào 0000:aaaa\n        CALL    nhanHex\n        MOV     AH, AL                  ; byte cao của địa chỉ\n        CALL    nhanHex\n        MOV     DI, AX\n        CALL    nhanHex                 ; AL = giá trị cần ghi\n        MOV     ES:[DI], AL             ; không kiểm DI!\n        MOV     AL, 'K'\n        CALL    gui\n        RET                             ; IP trả về lấy từ 3FFEh-3FFFh\nlenhW   ENDP\nnhanHex PROC    NEAR                    ; 2 chữ số hệ 16 -> AL (giữ AH)\n        CALL    nhan\n        CALL    hexVal\n        MOV     CL, 4\n        SHL     AL, CL\n        MOV     BL, AL\n        CALL    nhan\n        CALL    hexVal\n        OR      AL, BL\n        RET\nnhanHex ENDP\nhexVal  PROC    NEAR\n        SUB     AL, '0'\n        CMP     AL, 9\n        JBE     h1\n        SUB     AL, 7\nh1:\n        RET\nhexVal  ENDP\ngui     PROC    NEAR\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\nnhan    PROC    NEAR\n        IN      AL, CTRL51\n        TEST    AL, 02H\n        JZ      nhan\n        IN      AL, DATA51\n        RET\nnhan    ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "W3FFFFF", "note": "Bẫy: lệnh ghi không kiểm địa chỉ. W3FFFFF ghi FFh vào 03FFFh, byte cao của IP trả về mà CALL lenhW cất ở 3FFEh–3FFFh. Chữ K vẫn in ra, nhưng RET lấy IP = FF1Ch, CPU nạp lệnh ở 0BF1Ch (không có chip) và dừng. Sửa: kiểm giới hạn trước khi ghi (Ví dụ 7). Đoán trước: sau RET, IP bằng bao nhiêu? Đáp án FF1Ch.", "an": true}, {"label": "Ví dụ: lệnh ghi có kiểm giới hạn", "code": "; Ví dụ 7: lệnh ghi Waaaavv chỉ cho phép 0400h-3EFFh\nDATA51  EQU     98H\nCTRL51  EQU     9AH\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     ES, AX                  ; ES = 0: địa chỉ aaaa = 0000:aaaa\n        MOV     AL, 4EH\n        OUT     CTRL51, AL\n        MOV     AL, 37H\n        OUT     CTRL51, AL\nlap:\n        CALL    nhan\n        CMP     AL, 'W'\n        JNE     thoat\n        CALL    lenhW\n        JMP     lap\nthoat:\n        HLT\nlenhW   PROC    NEAR                    ; Waaaavv: ghi vv vào 0000:aaaa\n        CALL    nhanHex\n        MOV     AH, AL                  ; byte cao của địa chỉ\n        CALL    nhanHex\n        MOV     DI, AX\n        CALL    nhanHex                 ; AL = giá trị cần ghi\n        MOV     SI, OFFSET sLoi\n        CMP     DI, 0400H               ; dưới: bảng vectơ ngắt\n        JB      w9\n        CMP     DI, 3EFFH               ; trên: 3F00h-3FFFh dành cho ngăn xếp\n        JA      w9\n        MOV     ES:[DI], AL\n        MOV     SI, OFFSET sOk\nw9:\n        CALL    inChuoi                 ; báo OK hoặc ERR\n        RET\nlenhW   ENDP\nnhanHex PROC    NEAR                    ; 2 chữ số hệ 16 -> AL (giữ AH)\n        CALL    nhan\n        CALL    hexVal\n        MOV     CL, 4\n        SHL     AL, CL\n        MOV     BL, AL\n        CALL    nhan\n        CALL    hexVal\n        OR      AL, BL\n        RET\nnhanHex ENDP\nhexVal  PROC    NEAR\n        SUB     AL, '0'\n        CMP     AL, 9\n        JBE     h1\n        SUB     AL, 7\nh1:\n        RET\nhexVal  ENDP\ninChuoi PROC    NEAR                    ; in chuỗi CS:SI kết thúc bằng 0\n        MOV     AL, CS:[SI]\n        CMP     AL, 0\n        JE      ic9\n        CALL    gui\n        INC     SI\n        JMP     inChuoi\nic9:\n        RET\ninChuoi ENDP\ngui     PROC    NEAR\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\nnhan    PROC    NEAR\n        IN      AL, CTRL51\n        TEST    AL, 02H\n        JZ      nhan\n        IN      AL, DATA51\n        RET\nnhan    ENDP\nsOk     DB      'OK', 13, 10, 0\nsLoi    DB      'ERR', 13, 10, 0\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "W05003CW3FFFFFQ", "note": "Cùng lệnh W nhưng kiểm 0400h ≤ DI ≤ 3EFFh bằng JB, JA (so sánh không dấu). W05003C ghi 3Ch vào 00500h và in OK; W3FFFFF bị từ chối, in ERR, ngăn xếp còn nguyên nên RET đúng; Q dừng. Xem phần Bộ nhớ ở 00500h. Đoán trước: W03FF55 được ghi không? Đáp án không (bảng vectơ).", "an": true}];
const sim46=makeX86Trainer(document.getElementById("x86-l46"),{id:"s46",presets:P46,file:"ROM46.ASM"});
makeX86TrainerEx(document.getElementById("ex-l46"),sim46,[{"t": "Công tắc dạng nhị phân", "d": "Monitor cần in trạng thái 8 công tắc (PB, cổng 82h) ra terminal dưới dạng 8 ký tự 0 hoặc 1, bit 7 (PB7) in trước, bit 0 in sau cùng, không có ký tự nào khác; rồi dừng bằng HLT. Code mẫu đã khởi tạo ngăn xếp, 8251A, 8255A và có thủ tục gui (gửi AL khi TxRDY = 1, giữ nguyên mọi thanh ghi).", "start": "; Bài tập 1: in 8 công tắc dạng 8 chữ số nhị phân (PB7 trước)\nDATA51  EQU     98H\nCTRL51  EQU     9AH\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     AL, 4EH\n        OUT     CTRL51, AL\n        MOV     AL, 37H\n        OUT     CTRL51, AL\n        MOV     AL, 82H\n        OUT     86H, AL\n        IN      AL, 82H                 ; AL = công tắc\n; Viết code ở đây: in 8 ký tự '0'/'1' bằng gui,\n; bit 7 trước, bit 0 sau cùng\n        HLT\ngui     PROC    NEAR                    ; gửi AL, giữ nguyên mọi thanh ghi\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "tests": [{"sw": 0, "out": "00000000"}, {"sw": 255, "out": "11111111"}, {"sw": 181, "out": "10110101"}, {"sw": 1, "out": "00000001"}, {"sw": 128, "out": "10000000"}, {"sw": 60, "out": "00111100"}]}, {"t": "Lệnh xem bộ nhớ có giới hạn", "d": "Terminal gửi lệnh Daaaa (chữ D rồi 4 chữ số hệ 16 viết hoa). Nếu 0400h ≤ aaaa ≤ 3EFCh, in 4 byte ở 0000:aaaa … 0000:aaaa+3 dạng hai chữ số hệ 16 viết hoa, cách nhau đúng một dấu cách (ví dụ 3C 0A FF 12); ngược lại in ERR (bảng vectơ dưới 0400h, ngăn xếp từ 3F00h, ngoài RAM). Rồi dừng bằng HLT. Code mẫu đã đọc lệnh, AX = aaaa, DS = 0, có sẵn nhanHex, inHex, inChuoi, gui, nhan.", "start": "; Bài tập 2: lệnh Daaaa của monitor in 4 byte ở 0000:aaaa\nDATA51  EQU     98H\nCTRL51  EQU     9AH\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     DS, AX                  ; DS = 0: đọc 0000:aaaa\n        MOV     AL, 4EH\n        OUT     CTRL51, AL\n        MOV     AL, 37H\n        OUT     CTRL51, AL\n        CALL    nhan                    ; ký tự 'D'\n        CALL    nhanHex                 ; AL = 2 chữ số đầu của aaaa\n        MOV     AH, AL\n        CALL    nhanHex                 ; AX = aaaa\n; Viết code ở đây: aaaa phải từ 0400h tới 3EFCh;\n; in 4 byte dạng hệ 16, cách nhau một dấu cách\n        MOV     SI, OFFSET sLoi\n        CALL    inChuoi                 ; ngoài giới hạn: in ERR\n        HLT\nnhanHex PROC    NEAR                    ; 2 chữ số hệ 16 -> AL (giữ AH)\n        CALL    nhan\n        CALL    hexVal\n        MOV     CL, 4\n        SHL     AL, CL\n        MOV     BL, AL\n        CALL    nhan\n        CALL    hexVal\n        OR      AL, BL\n        RET\nnhanHex ENDP\nhexVal  PROC    NEAR\n        SUB     AL, '0'\n        CMP     AL, 9\n        JBE     h1\n        SUB     AL, 7\nh1:\n        RET\nhexVal  ENDP\ninHex   PROC    NEAR                    ; in AL dạng 2 chữ số hệ 16 (đổi CL)\n        PUSH    AX\n        MOV     CL, 4\n        SHR     AL, CL\n        CALL    inNib\n        POP     AX\n        AND     AL, 0FH\n        CALL    inNib\n        RET\ninHex   ENDP\ninNib   PROC    NEAR\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     n1\n        ADD     AL, 7\nn1:\n        CALL    gui\n        RET\ninNib   ENDP\ninChuoi PROC    NEAR                    ; in chuỗi CS:SI kết thúc bằng 0\n        MOV     AL, CS:[SI]\n        CMP     AL, 0\n        JE      ic9\n        CALL    gui\n        INC     SI\n        JMP     inChuoi\nic9:\n        RET\ninChuoi ENDP\ngui     PROC    NEAR\n        PUSH    AX\ng1:\n        IN      AL, CTRL51\n        TEST    AL, 01H\n        JZ      g1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\nnhan    PROC    NEAR\n        IN      AL, CTRL51\n        TEST    AL, 02H\n        JZ      nhan\n        IN      AL, DATA51\n        RET\nnhan    ENDP\nsLoi    DB      'ERR', 0\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "tests": [{"in": "D0400", "out": "88 3B 27 7B"}, {"in": "D1234", "out": "CB C6 A5 3A"}, {"in": "D3EFC", "out": "DE 84 A2 BE"}, {"in": "D3EFD", "out": "ERR"}, {"in": "D03FF", "out": "ERR"}, {"in": "D0000", "out": "ERR"}, {"in": "DFC00", "out": "ERR"}, {"in": "D2001", "out": "2A AE ED A5"}]}, {"t": "Tổng kiểm tra RAM nhanh", "d": "Monitor có lệnh tính tổng kiểm tra 8 bit (cộng mọi byte, bỏ phần tràn, tức tổng mod 256) của N × 256 byte RAM bắt đầu từ 00400h, với N là giá trị công tắc PB (1–15); đưa kết quả ra LED (PA) rồi HLT. Code mẫu đúng nhưng chậm. Viết lại để mọi test chạy không quá 70 000 chu kỳ CPU và mã không quá 42 byte (tính cả lệnh JMP xa ở FFFF0h).", "start": "; Bài tập 3: tổng kiểm tra 8 bit của N x 256 byte RAM từ 00400h\n; Bản này đúng nhưng chậm: mỗi byte một vòng LODSB.\nPA      EQU     80H\nPB      EQU     82H\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        MOV     AL, 82H\n        OUT     86H, AL\n        IN      AL, PB                  ; N = 1-15\n        MOV     AH, AL\n        XOR     AL, AL                  ; AX = N x 256 byte\n        MOV     CX, AX\n        MOV     AX, 0040H               ; DS:SI = 0040:0000 = 00400h\n        MOV     DS, AX\n        XOR     SI, SI\n        XOR     BL, BL                  ; BL = tổng\n        CLD\ncong:\n        LODSB                           ; 12 chu kỳ\n        ADD     BL, AL                  ; 3 chu kỳ, tràn bỏ đi (mod 256)\n        LOOP    cong                    ; 17 chu kỳ khi nhảy\n        MOV     AL, BL\n        OUT     PA, AL                  ; LED = tổng 8 bit\n        HLT\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "tests": [{"sw": 1, "leds": 161}, {"sw": 2, "leds": 149}, {"sw": 5, "leds": 192}, {"sw": 8, "leds": 177}, {"sw": 15, "leds": 101}], "perf": {"cycles": 70000, "bytes": 42}}]);

makeQuiz("quiz46","score46",[{"q": "Biến <code>dem DB 5<\/code> khai báo trong <code>RAM SEGMENT<\/code> của chương trình trainer. Ngay sau RESET, ô của <code>dem<\/code> chứa gì?", "o": ["Số 5, vì trình dịch ghi giá trị đầu vào RAM", "Không xác định, cho tới khi chương trình tự ghi", "Số 0, vì RAM luôn được xóa khi bật nguồn", "FFh, vì ô RAM chưa ghi luôn đọc ra FFh"], "a": 1, "e": "RAM mất nội dung khi tắt nguồn và không ai nạp tệp chương trình vào RAM như DOS. Giá trị 5 phải đặt trong EPROM và được chép sang bằng mã khởi động (Ví dụ 2); trình mô phỏng còn cảnh báo khi dịch."}, {"q": "Đoạn sau chạy với 8251A vừa RESET. Chuyện gì xảy ra?<pre class=\"mp-asm\">        MOV     AL, 37H\n        OUT     9AH, AL\n        MOV     AL, 4EH\n        OUT     9AH, AL\n        MOV     AL, 'K'\n        OUT     98H, AL<\/pre>", "o": ["Chữ K không được gửi: 4Eh bị hiểu là từ lệnh có IR = 1", "Chữ K được gửi vì 8251A tự nhận ra đâu là từ chế độ", "Chữ K được gửi hai lần vì có hai byte điều khiển", "Chip báo lỗi chẵn lẻ và gửi chữ K với khung 7 bit"], "a": 0, "e": "Byte đầu sau RESET luôn là từ chế độ, byte sau là từ lệnh. 4Eh = 0100 1110b có bit 6 (IR) = 1 nên là lệnh reset trong; chip quay lại chờ từ chế độ và không gửi dữ liệu (Ví dụ 5)."}, {"q": "AL = 0Ch. Thủ tục sau gửi ký tự nào ra terminal?<pre class=\"mp-asm\">inNib:  ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     n1\n        ADD     AL, 7\nn1:     CALL    gui<\/pre>", "o": ["'&lt;' (3Ch): ký tự ngay sau '9' trong bảng ASCII", "'L' (4Ch): vì ADD AL, 7 cộng vào 45h", "'12': hai chữ số thập phân của số 12", "'C' (43h): 0Ch + 30h = 3Ch > '9' nên cộng thêm 7"], "a": 3, "e": "0Ch + 30h = 3Ch (ký tự '<'), lớn hơn '9' = 39h nên cộng 7: 43h = 'C'. Giữa '9' và 'A' có đúng 7 ký tự ASCII."}, {"q": "Ở 9600 baud, khung 8N1, CPU 5 MHz, gửi liên tục một chuỗi 100 ký tự mất khoảng bao lâu trên bo thật?", "o": ["Khoảng 104 ms, vì mỗi ký tự là 10 bit trên dây", "Khoảng 83 ms, vì mỗi ký tự chỉ có 8 bit dữ liệu", "Khoảng 1,5 ms, bằng số chu kỳ của thủ tục gui", "Khoảng 10 ms, vì 9600 baud là 9600 byte mỗi giây"], "a": 0, "e": "8N1 = 1 start + 8 dữ liệu + 1 stop = 10 bit; 100 × 10 / 9600 ≈ 0,104 s. Thời gian CPU chạy lệnh (khoảng 74 chu kỳ = 15 µs mỗi ký tự) nhỏ hơn nhiều; vòng hỏi TxRDY chờ phần còn lại. Trainer ảo không mô phỏng thời gian này."}, {"q": "Monitor cho đọc 4 byte bắt đầu ở 0000:aaaa, vùng được phép 0400h–3EFFh. Điều kiện nào đúng cho aaaa (so sánh không dấu)?", "o": ["0400h ≤ aaaa ≤ 3EFFh", "0400h &lt; aaaa &lt; 3F00h", "aaaa ≥ 0400h là đủ", "0400h ≤ aaaa ≤ 3EFCh"], "a": 3, "e": "Byte cuối là aaaa + 3, cũng phải ≤ 3EFFh, nên aaaa ≤ 3EFCh. Với aaaa = 3EFDh, byte cuối 3F00h đã thuộc vùng ngăn xếp (bài tập 2 có test biên này)."}]);

